```js
function clothGeometry(w, h, cols, rows, taper, drape){
  const g = new THREE.PlaneGeometry(1, h, cols, rows);
  const pos = g.attributes.position;
  for (let i=0;i<pos.count;i++){
    const y = pos.getY(i);
    const t = clamp(0.5 - y/h, 0, 1);
    pos.setX(i, pos.getX(i) * lerp(1, taper, t));
    pos.setZ(i, -drape * t*t);
  }
  g.computeVertexNormals();
  return g;
}
const capeGeo = clothGeometry(0.62,0.94,5,6,0.68,0.06);
